    used.add(owner)
    ack = dict(original['ack_base'], status='ROOT_RUN_ACK', no_actual_approval=False, owner=owner, range=job['range'])
    digest = hashlib.sha256((json.dumps(ack, indent=2, ensure_ascii=False) + '\n').encode()).hexdigest()
    assert new_raw.count(job['owner'].encode()) == 1 and new_raw.count(job['ack_sha256'].encode()) == 1
    new_raw = new_raw.replace(job['owner'].encode(), owner.encode()).replace(job['ack_sha256'].encode(), digest.encode())
    replacements.append({'ordinal': job['ordinal'], 'lane': job['lane'], 'range': job['range'], 'old_owner': job['owner'], 'new_owner': owner, 'old_ACK_sha256': job['ack_sha256'], 'new_ACK_sha256': digest})
